openai_chat.curl:
API_KEY="your_api_key"
# 平台底层维护了多个上游账号，为了保证亲和性 cache_task_id 参数配置能保证 cache 缓存命中率, 具体参数解释 https://iwiki.woa.com/p/4051772719 务必替换成cache_task_id=<32位MD5>
CACHE_TASK_ID=$(python3 -c "import hashlib; print(hashlib.md5(('chat_demo:${API_KEY}').encode()).hexdigest())")
curl -X POST 'http://api.aihub.woa.com/standard/v1/chat/completions' \
  -H "Authorization: Bearer ${API_KEY}?cache_task_id=${CACHE_TASK_ID}" \
  -H 'Content-Type: application/json' \
  -d '{
    "model": "hy4-preview",
    "messages": [
      {"role": "user", "content": "请用JSON格式回答：你好"}
    ],
    "reasoning_effort": "high",
    "prompt_cache_key": "hy4-preview-example",
    "max_completion_tokens": 4096,
    "temperature": 0.9,
    "top_p": 1.0,
    "stream": false,
    "response_format": {"type": "json_object"},
    "tools": [
      {"type": "function", "function": {
        "name": "get_weather",
        "description": "获取城市天气",
        "parameters": {
          "type": "object",
          "properties": {
            "city": {"type": "string", "description": "城市名"}},
          "required": ["city"]}}}
    ],
    "tool_choice": "auto"
  }'

